function journeySample(d,index=0){const t=d.topics[index]||d.topics[0];if(t.sampleKey&&typeof getPrototypeSample==='function'){const sample=getPrototypeSample(t.sampleKey);if(sample)return sample;}return {title:t.title,body:d.open+'\n\n'+t.argument+'\n\n阅读后可以找一句想改写的表达，并核查它的适用条件。此处是预置样稿摘录。',xhsTitle:t.title,xhsText:d.open,cards:[{label:'01 / 问题',title:t.title,body:t.argument},{label:'02 / 方法',title:'先区分，再判断',body:d.open}]};}
function journeyMiniCards(parent,sample,limit=2){const grid=node('div','journey-sample-cards');(sample.cards||[]).slice(0,limit).forEach((c,i)=>grid.append(append(node('div','journey-mini-card'),node('small','',c.label||String(i+1).padStart(2,'0')),node('h4','',c.title||sample.title),node('p','',c.body||''))));parent.append(grid);}
