function journeyTrialCount(){const j=journeyState();return Math.max(1,Math.min(journeyTopics().length,Number(j.trialCount)||1));}
function journeyTrialHistory(i){const j=journeyState();return (state.history||[]).filter(h=>h.task&&h.task.workspaceId===j.activeWorkspaceId&&h.task.trialDirection===j.directionId&&h.task.trialItem===i&&h.task.trialRound===j.trialRound);}
function journeyOpenTask(task){journeyGuard(()=>{if(task.workspaceId!==journeyState().activeWorkspaceId){journeyActivateWorkspace(task.workspaceId,null);}state.task=journeyClone(task);go('content');});}
function journeyHistory(parent){const j=journeyState();const p=panel('最近稿件 · 当前工作空间');const history=(state.history||[]).filter(h=>h.task&&h.task.workspaceId===j.activeWorkspaceId);p.append(node('p','journey-caption','仅显示本空间；其他空间的稿件仍保留在全局会话历史。刷新不保留。'));if(!j.activeWorkspaceId||!history.length)p.append(node('p','','还没有稿件。先看一篇预置样稿即可。'));history.slice().reverse().forEach(h=>p.append(append(node('div','journey-history'),append(node('div'),node('h3','',h.title),node('p','journey-caption',h.id)),chip(h.status||'待审核'),button('查看版本',()=>journeyOpenTask(h.task)))));parent.append(p);}
function renderTrialPlan(){const j=journeyState();if(!j.activeWorkspaceId){heading('TRY A DIRECTION','先看方向，再选一篇','无需问卷或模型接入。');main.append(button('看推荐方向',()=>journeyGo('explore'),'button primary'));return;}const d=journeyDirection();heading('ONE SMALL TRY · '+d.name,state.profile.brand+' · 本轮试做','先看预置离线样稿，不是免费 AI；无实际生成、发布或支付。',button('直接看第一篇样稿 →',()=>journeyGuard(()=>startTrialContent(0,'preview')),'button primary'));journeyWorkspaceSwitch(main);append(main,actions(button('返回工作空间',()=>journeyGo('workspace')),button('返回平台看方向',()=>journeyGo('explore'))));const p=panel('本轮试做篇数 · 你来选');const counts=actions();d.topics.forEach((_,i)=>{const n=i+1,b=button(n+' 篇',()=>journeyGuard(()=>{j.trialCount=n;journeySaveWorkspace();render();}),'button'+(journeyTrialCount()===n?' active':''));b.setAttribute('aria-pressed',String(journeyTrialCount()===n));counts.append(b);});append(p,node('p','','默认 1 篇。不根据空闲时间推断，也不承诺完成时长；选篇数不会创建任务或定时计划。'),counts,journeyNote(d.rules));main.append(p);journeyTopics().slice(0,journeyTrialCount()).forEach((t,i)=>{const history=journeyTrialHistory(i),card=panel();card.classList.add('journey-trial');append(card,chip('试做 '+(i+1)+' / '+journeyTrialCount()),chip(history.length?'已有 '+history.length+' 个版本':'尚未试做'),node('h2','',t.title),node('p','',t.argument),actions(button('看预置离线样稿',()=>journeyGuard(()=>startTrialContent(i,'preview')),'button primary'),button('已连接模型流程（模拟）',()=>journeyGuard(()=>startTrialContent(i,'connected')))));if(history.length)card.append(button('查看最近版本',()=>journeyOpenTask(history[history.length-1].task),'text-button'));main.append(card);});renderDirectionCard(main);append(main,actions(button('记录 / 回看感受',()=>journeyGo('feedback')),button('可选：了解模型接入',()=>journeyGo('providers'),'text-button')));}
function journeyFeedbackSuggestion(f){if(f.difficulty==='hard')return {title:'先减轻一点负担',text:'可以只试一篇，找出一句不懂的表达；不发布也可以复盘。'};if(f.difficulty==='easy')return {title:'愿意的话，再看一篇',text:'读起来顺是一个感受，不代表材料已经核验，也不代表方向已经成功。'};return {title:'暂时不知道，也没关系',text:'可以继续看样稿、先停一下，或返回平台看看其他方向。无需现在决定长期方向。'};}
function journeySaveFeedback(skip){const j=journeyState(),f=j.feedbackDraft;j.feedback={published:skip?'unknown':f.published||'unknown',difficulty:skip?'unknown':f.difficulty||'unknown',question:skip?'':String(f.question||'').trim().slice(0,500),skipped:!!skip,saved:true};j.feedbackRecords.push({...j.feedback,workspaceId:j.activeWorkspaceId,trialRound:j.trialRound});journeySaveWorkspace();render();toast('仅保存当前空间的自报感受，没有读取平台指标。');}
function renderTrialFeedback(){const j=journeyState();heading('REFLECT · 仅自报',j.activeWorkspaceId?state.profile.brand+' · 本轮感受':'随时可以记录感受','可全部跳过；不要求阅读量、粉丝或收入，不读取发布状态。');if(!j.activeWorkspaceId){main.append(button('先看方向',()=>journeyGo('explore'),'button primary'));return;}const p=panel('这次体验如何？');[['published','是否已自行发布？',[['yes','已自行发布'],['no','未发布'],['unknown','不知道 / 跳过']]],['difficulty','读起来、准备起来怎样？',[['easy','大体能懂'],['hard','有点难'],['unknown','不知道 / 跳过']]]].forEach(([key,label,opts])=>{const group=node('div','journey-feedback-group');group.setAttribute('role','group');group.setAttribute('aria-label',label);group.append(node('h3','',label));const row=node('div','journey-feedback-options');opts.forEach(([val,text])=>{const b=button(text,()=>{j.feedbackDraft[key]=val;journeySaveWorkspace();render();},'journey-choice'+(j.feedbackDraft[key]===val?' journey-selected':''));b.setAttribute('aria-pressed',String(j.feedbackDraft[key]===val));row.append(b);});append(p,append(group,row));});const note=textarea(j.feedbackDraft.question||'');note.rows=3;note.maxLength=500;note.placeholder='哪句话不懂、哪一步卡住，或想改哪里？可留空。';note.addEventListener('input',()=>{j.feedbackDraft.question=note.value;});append(p,field('留一句感受（可跳过）',note,'不要填写个人、公司或同事隐私。'),actions(button('保存这次感受',()=>journeySaveFeedback(false),'button primary'),button('全部跳过',()=>journeySaveFeedback(true))));main.append(p);if(j.feedback.saved){const s=journeyFeedbackSuggestion(j.feedback);const result=panel(s.title);append(result,node('p','',s.text),actions(button('继续本轮试做',()=>journeyGo('plan')),button('先保留 1 篇',()=>journeyGuard(()=>{j.trialCount=1;journeySaveWorkspace();go('plan');})),button('看看其他方向',()=>journeyGo('explore'))));main.append(result);}if(j.feedbackRecords.length){const records=panel('本空间反馈记录 · 第 '+j.trialRound+' 轮');j.feedbackRecords.slice().reverse().forEach((r,i)=>records.append(append(node('div','journey-feedback-record'),node('h3','','记录 '+(j.feedbackRecords.length-i)+(r.skipped?' · 已跳过':'')),node('p','','发布：'+({yes:'自报已发布',no:'未发布',unknown:'未提供'}[r.published]||'未提供')+' / 感受：'+({easy:'大体能懂',hard:'有点难',unknown:'未提供'}[r.difficulty]||'未提供')),node('p','',r.question||'未填写文字感受'))));main.append(records);}}
